"""Fetch all orders and customers from the order service, keeping a log of
every non-200 response so that anomalies are visible."""
import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
LOG = []  # every non-200 response seen: (method, path, status, detail)


def note(method, path, status, detail=""):
    LOG.append((method, path, status, detail))
    print(f"[{method} {path}] {status} {detail}", file=sys.stderr)


def raw(method, path, token=None):
    headers = {}
    if token:
        headers["Authorization"] = f"Bearer {token}"
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, dict(r.headers), r.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read().decode(errors="replace")


class Client:
    def __init__(self):
        self.token = None

    def get_token(self):
        status, _, body = raw("POST", "/token")
        if status != 200:
            raise RuntimeError(f"token request failed: {status} {body}")
        self.token = json.loads(body)["token"]
        return self.token

    def get(self, path, max_tries=50):
        """GET an authenticated path, retrying on 401 (refresh token),
        429 (honour the wait), 5xx and network errors."""
        if self.token is None:
            self.get_token()
        for attempt in range(1, max_tries + 1):
            try:
                status, headers, body = raw("GET", path, self.token)
            except OSError as e:
                note("GET", path, "NETWORK", f"{e!r} attempt {attempt}")
                time.sleep(min(2 ** attempt, 30))
                continue
            if status == 200:
                return json.loads(body)
            note("GET", path, status, f"attempt {attempt} headers={headers.get('Retry-After')} body={body[:300]}")
            if status == 401 or status == 403:
                self.get_token()
            elif status == 429:
                wait = headers.get("Retry-After")
                try:
                    wait = float(wait)
                except (TypeError, ValueError):
                    wait = 5.0
                time.sleep(wait + 0.5)
            elif status == 404:
                return None
            else:
                time.sleep(min(2 ** attempt, 30))
        raise RuntimeError(f"gave up on {path} after {max_tries} attempts")


def main():
    c = Client()
    c.get_token()

    # Page 1 tells us how many pages there are.
    first = c.get("/orders?page=1")
    total_pages = first["total_pages"]
    pages = {1: first}
    for p in range(2, total_pages + 1):
        pages[p] = c.get(f"/orders?page={p}")

    # Cross-check the "next" chain against page numbers.
    chain = []
    path = "/orders?page=1"
    seen_paths = set()
    while path and path not in seen_paths:
        seen_paths.add(path)
        chain.append(path)
        path = c.get(path)["next"]
    chain_pages = [int(p.split("page=")[1]) for p in chain]

    orders_all = []
    for p in range(1, total_pages + 1):
        if pages[p]["page"] != p:
            note("INFO", f"page {p}", "MISMATCH", f"body says page {pages[p]['page']}")
        orders_all.extend(pages[p]["items"])

    result = {
        "total_pages": total_pages,
        "next_chain_pages": chain_pages,
        "next_chain_matches_page_numbers": chain_pages == list(range(1, total_pages + 1)),
        "listed_rows": len(orders_all),
        "orders": orders_all,
    }

    # Customers, fetched once each.
    cust_ids = sorted({o["customer_id"] for o in orders_all})
    customers = {}
    for cid in cust_ids:
        customers[cid] = c.get(f"/customers/{cid}")
    result["customers"] = customers
    result["fetch_log"] = LOG

    with open("/tmp/recon/raw.json", "w") as f:
        json.dump(result, f)

    print(
        f"pages={total_pages} rows={len(orders_all)} "
        f"chain_ok={result['next_chain_matches_page_numbers']} "
        f"customers={len(customers)} "
        f"missing_customers={[k for k, v in customers.items() if v is None]} "
        f"non200_events={len(LOG)}",
        file=sys.stderr,
    )


if __name__ == "__main__":
    main()

